def take_quiz():
    """Administer a quiz with multiple-choice questions."""

    # Define the quiz questions and answers
    quiz_questions = {
        "Question 1": {
            "question": "What is the capital of France?",
            "answers": {
                "A": "Paris",
                "B": "Berlin",
                "C": "London",
                "D": "Rome"
            }
        },
        "Question 2": {
            "question": "Who is the current Prime Minister of the UK?",
            "answers": {
                "A": "Boris Johnson",
                "B": "Theresa May",
                "C": "Jeremy Corbyn",
                "D": "Nigel Farage"
            }
        }
    }

    score = 0

    print("Take quiz")

    for question_number, question in quiz_questions.items():
        print(f"Question {question_number}: {question['question']}")

        for answer_letter, correct_answer in question['answers'].items():
            print(f"\t{answer_letter}: {correct_answer}")

        user_answer = input("Enter your answer (A, B, C, or D): ").upper()

        if user_answer in question['answers']:
            correct_answer = question['answers'][user_answer]
            if correct_answer == input("Is this correct? (Y/N): ").upper() == "Y":
                score += 1
                print(f"Correct! Your score is now {score}.")
            else:
                print(f"Sorry, that's incorrect. The correct answer is {correct_answer}.")
        else:
            print(f"Sorry, that's not a valid answer. Please try again.")

    print(f"\nYour final score is {score} out of 2.")


if __name__ == "__main__":
    take_quiz()
```

You can modify the `quiz_questions` dictionary to add more questions and answers as needed.
